{
  "appName": "RecipeShare",
  "appType": "recipe sharing",
  "summary": "A recipe sharing app where users can post recipes, comment on them, and premium users get access to weekly meal planning.",
  "entities": [
    {
      "name": "recipe",
      "fields": ["title", "description", "ingredients", "steps", "authorId"]
    },
    {
      "name": "comment",
      "fields": ["recipeId", "userId", "text", "timestamp"]
    },
    {
      "name": "mealPlan",
      "fields": ["userId", "weekStartDate", "recipes"]
    }
  ],
  "roles": ["user", "premium user"],
  "features": ["auth", "recipe posting", "commenting", "meal planning"],
  "hasAuth": true,
  "hasPayments": false,
  "ambiguities": [],
  "assumptions": [
    "Users will have accounts to post recipes and comments.",
    "Premium user status will be managed, though the payment mechanism is not specified.",
    "Recipes will have a title, description, ingredients list, and steps."
  ],
  "clarifyingQuestions": []
}
